package dev.javacpp.compat.python;

import static org.junit.jupiter.api.Assertions.*;

import dev.javacpp.python.PythonException;
import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.*;
import org.junit.jupiter.api.*;

/**
 * Replays seeded-random Jinja templates generated by
 * tools/python_compat/generate_jinjafuzz_contracts.py. Successful renders compare output text
 * exactly; real-jinja2 failures require the Java adapter to fail as well (the exception class
 * is advisory since jinjava does not report CPython type names).
 */
class PythonJinjaFuzzContractTest {
  @TestFactory
  Stream<DynamicTest> jinjaFuzz() throws Exception {
    List<String> lines;
    try (var input =
        Objects.requireNonNull(
            getClass().getResourceAsStream("/python-0.3.36-jinjafuzz-contracts.tsv"),
            "Run generate_jinjafuzz_contracts.py")) {
      lines = new String(input.readAllBytes(), StandardCharsets.US_ASCII).lines().toList();
    }
    return IntStream.range(0, lines.size())
        .mapToObj(i -> DynamicTest.dynamicTest("jinjafuzz:" + i, () -> run(lines.get(i), i)));
  }

  @SuppressWarnings("unchecked")
  private static void run(String line, int index) throws Exception {
    String[] parts = line.split("\t");
    Map<String, Object> argument = (Map<String, Object>) read(parts[0]);
    Map<String, Object> expected = (Map<String, Object>) read(parts[1]);
    Map<String, Object> actual = new HashMap<>();
    try {
      var renderer =
          new PythonJinjaTemplate((String) argument.get("template"), "<eos>", "<bos>");
      actual.put("output", renderer.render(bindings(argument)));
    } catch (PythonException error) {
      actual.put("error", error.type().pythonName());
    } catch (RuntimeException error) {
      actual.put("error", "java:" + error.getClass().getSimpleName());
    }
    if (expected.containsKey("error")) {
      assertTrue(
          actual.containsKey("error"),
          "case=" + index + " expected failure but rendered " + abbreviate(actual.get("output")));
    } else {
      assertEquals(
          expected, actual, "case=" + index + " template=" + argument.get("template"));
    }
  }

  @SuppressWarnings("unchecked")
  private static Map<String, Object> bindings(Map<String, Object> argument) {
    return new LinkedHashMap<>((Map<String, Object>) argument.get("bindings"));
  }

  private static String abbreviate(Object value) {
    String text = String.valueOf(value);
    return text.length() > 120 ? text.substring(0, 120) + "..." : text;
  }

  private static Object read(String value) throws Exception {
    return PythonContractData.read(
        new DataInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(value))));
  }
}
